package ua.empirecraft.feudal;
import java.sql.SQLException;
import java.util.*;
import static ua.empirecraft.feudal.Database.*;
import static ua.empirecraft.feudal.Model.*;
import ua.empirecraft.feudal.FeudalService.Actor;

public final class SuccessionService {
    public interface Authority {void validate(Estate e,String heir) throws Exception;String leader(Estate e) throws Exception;void transfer(Estate e,String heir) throws Exception;boolean online(String player);}
    private final FeudalService s;private final Database db;private final Authority authority;private final long inactivity;private final Map<String,Long> retryAfter=new HashMap<>();
    public SuccessionService(FeudalService s,Authority authority,int days) throws SQLException {this.s=s;db=s.db;this.authority=authority;require(days>=7&&days<=365,"Неактивність: 7–365 днів.");inactivity=days*FeudalService.DAY;
        db.execute("CREATE TABLE IF NOT EXISTS dynasties (id VARCHAR(36) PRIMARY KEY,name VARCHAR(48),founder VARCHAR(36) UNIQUE,created BIGINT)");db.execute("CREATE TABLE IF NOT EXISTS dynasty_members (house VARCHAR(36),person VARCHAR(36),joined BIGINT,PRIMARY KEY(house,person))");
        db.execute("CREATE TABLE IF NOT EXISTS heirs (estate VARCHAR(80) PRIMARY KEY,lord VARCHAR(36),heir VARCHAR(36),house VARCHAR(36),accepted BOOLEAN,created BIGINT)");db.execute("CREATE TABLE IF NOT EXISTS ruler_activity (person VARCHAR(36) PRIMARY KEY,last_seen BIGINT)");
        db.execute("CREATE TABLE IF NOT EXISTS succession_ops (id VARCHAR(36) PRIMARY KEY,estate VARCHAR(80),previous_lord VARCHAR(36),heir VARCHAR(36),house VARCHAR(36),reason VARCHAR(32),status VARCHAR(16),created BIGINT)");db.execute("CREATE TABLE IF NOT EXISTS dynasty_history (seq BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,estate VARCHAR(80),at_time BIGINT,actor VARCHAR(80),event VARCHAR(32),detail CLOB)");}
    private void log(String estate,Actor actor,String event,String detail) throws SQLException {db.execute("INSERT INTO dynasty_history(estate,at_time,actor,event,detail) VALUES(?,?,?,?,?)",estate,s.now(),actor.id(),event,detail);s.audit(actor,"DYNASTY_"+event,estate+" "+detail);}
    public String create(Actor actor,String name){return db.transaction(()->{validName(name);require(db.one("SELECT id FROM dynasties WHERE founder=?",actor.id())==null,"Ви вже заснували династію.");String id=UUID.randomUUID().toString();db.execute("INSERT INTO dynasties VALUES(?,?,?,?)",id,name,actor.id(),s.now());db.execute("INSERT INTO dynasty_members VALUES(?,?,?)",id,actor.id(),s.now());s.audit(actor,"DYNASTY_CREATE",id+" "+name);return id;});}
    public void nominate(Actor actor,String estate,String heir){db.transaction(()->{
        Estate e=s.estate(estate);require(e.active()&&Objects.equals(e.lord(),actor.id()),"Призначає лише чинний правитель.");require(!actor.id().equals(heir),"Оберіть іншого спадкоємця.");UUID.fromString(heir);authority.validate(e,heir);require(db.one("SELECT id FROM succession_ops WHERE estate=? AND status='PREPARED'",estate)==null,"Спочатку завершіть попередню передачу.");
        var house=db.one("SELECT * FROM dynasties WHERE founder=?",actor.id());if(house==null)house=db.one("SELECT d.* FROM dynasties d JOIN dynasty_members m ON d.id=m.house WHERE m.person=? ORDER BY m.joined LIMIT 1",actor.id());require(house!=null,"Спочатку /dynasty create Назва.");db.execute("MERGE INTO heirs KEY(estate) VALUES(?,?,?,?,FALSE,?)",estate,actor.id(),heir,string(house,"id"),s.now());log(estate,actor,"NOMINATE",heir);return null;
    });}
    public Map<String,Object> heir(String estate) throws SQLException {return db.one("SELECT h.*,d.name AS house_name FROM heirs h JOIN dynasties d ON d.id=h.house WHERE estate=?",estate);}
    public void accept(Actor actor,String estate){db.transaction(()->{var h=heir(estate);Estate e=s.estate(estate);require(h!=null&&actor.id().equals(string(h,"heir"))&&e.active()&&Objects.equals(e.lord(),string(h,"lord")),"Немає чинного призначення для вас.");authority.validate(e,actor.id());require(!bool(h,"accepted"),"Ви вже погодилися.");db.execute("UPDATE heirs SET accepted=TRUE WHERE estate=?",estate);db.execute("MERGE INTO dynasty_members KEY(house,person) VALUES(?,?,?)",string(h,"house"),actor.id(),s.now());log(estate,actor,"ACCEPT",actor.id());return null;});}
    public void revoke(Actor actor,String estate){db.transaction(()->{Estate e=s.estate(estate);require(e.active()&&Objects.equals(e.lord(),actor.id()),"Відкликає лише правитель.");require(db.one("SELECT id FROM succession_ops WHERE estate=? AND status='PREPARED'",estate)==null,"Передача вже розпочалася.");db.execute("DELETE FROM heirs WHERE estate=?",estate);log(estate,actor,"REVOKE","Спадкоємця відкликано");return null;});}
    public void touch(String player){db.transaction(()->{db.execute("MERGE INTO ruler_activity KEY(person) VALUES(?,?)",player,s.now());return null;});}
    public long lastSeen(String player) throws SQLException {var row=db.one("SELECT * FROM ruler_activity WHERE person=?",player);return row==null?s.now():number(row,"last_seen");}
    private String prepare(Actor actor,String estate,boolean inactive){return db.transaction(()->{
        Estate e=s.estate(estate);var h=heir(estate);require(e.active()&&h!=null&&bool(h,"accepted")&&Objects.equals(e.lord(),string(h,"lord")),"Потрібен чинний спадкоємець, який погодився.");if(inactive)require(!authority.online(e.lord())&&s.now()-lastSeen(e.lord())>=inactivity,"Правитель ще активний.");else require(Objects.equals(actor.id(),e.lord()),"Зректися може лише сам правитель.");authority.validate(e,string(h,"heir"));require(db.one("SELECT id FROM succession_ops WHERE estate=? AND status='PREPARED'",estate)==null,"Передача вже розпочалася.");String id=UUID.randomUUID().toString();db.execute("INSERT INTO succession_ops VALUES(?,?,?,?,?,?,'PREPARED',?)",id,estate,e.lord(),string(h,"heir"),string(h,"house"),inactive?"INACTIVITY":"ABDICATION",s.now());log(estate,actor,"PREPARE",id);return id;
    });}
    public void abdicate(Actor actor,String estate) throws Exception {complete(prepare(actor,estate,false));}
    private void complete(String id) throws Exception {
        var op=db.one("SELECT * FROM succession_ops WHERE id=?",id);require(op!=null&&"PREPARED".equals(string(op,"status")),"Передачу вже завершено.");Estate e=s.estate(string(op,"estate"));String previous=string(op,"previous_lord"),next=string(op,"heir");require(e.active(),"Володіння більше не існує.");boolean regional=e.kind()==Kind.DUCHY||e.kind()==Kind.COUNTY;String actual=regional?e.lord():authority.leader(e);require(Objects.equals(actual,previous)||Objects.equals(actual,next),"Правитель змінився поза системою. Потрібна перевірка.");
        if(!Objects.equals(actual,next)){authority.validate(e,next);if(!regional)authority.transfer(e,next);}if(!regional)require(Objects.equals(authority.leader(e),next),"Towny не підтвердив нового правителя.");
        db.transaction(()->{db.execute("UPDATE estates SET lord=? WHERE id=?",next,e.id());db.execute("UPDATE succession_ops SET status='APPLIED' WHERE id=?",id);db.execute("DELETE FROM heirs WHERE estate=? AND lord=?",e.id(),previous);db.execute("MERGE INTO ruler_activity KEY(person) VALUES(?,?)",next,s.now());log(e.id(),new Actor(next,false),"TRANSFER",previous+" -> "+next+"; "+string(op,"reason"));return null;});
    }
    public List<Map<String,Object>> pending() throws SQLException {return db.query("SELECT * FROM succession_ops WHERE status='PREPARED' ORDER BY created LIMIT 50");}
    public void abandon(Actor actor,String id){db.transaction(()->{require(actor.admin(),"Потрібне право адміністратора.");var op=db.one("SELECT * FROM succession_ops WHERE id=? AND status='PREPARED'",id);require(op!=null,"Незавершену передачу не знайдено.");Estate e=s.estate(string(op,"estate"));String actual=e.kind()==Kind.DUCHY||e.kind()==Kind.COUNTY?e.lord():authority.leader(e);require(!Objects.equals(actual,string(op,"heir")),"Спадкоємець уже керує: завершіть запис передачі.");db.execute("UPDATE succession_ops SET status='CANCELLED' WHERE id=?",id);db.execute("DELETE FROM heirs WHERE estate=? AND lord=?",e.id(),string(op,"previous_lord"));log(e.id(),actor,"CANCEL",id+"; чинна влада збережена");return null;});}
    public List<String> tick() throws Exception {
        var issues=new ArrayList<String>();for(Estate e:s.estates())if(e.active()&&e.lord()!=null){if(authority.online(e.lord())||db.one("SELECT person FROM ruler_activity WHERE person=?",e.lord())==null)touch(e.lord());}
        for(var op:pending()){String id=string(op,"id");if(s.now()<retryAfter.getOrDefault(id,0L))continue;try{complete(id);retryAfter.remove(id);}catch(Exception ex){retryAfter.put(id,s.now()+3_600_000L);issues.add(id+": "+ex.getMessage());}}
        for(var h:db.query("SELECT * FROM heirs WHERE accepted=TRUE")){Estate e=s.estate(string(h,"estate"));if(e.active()&&Objects.equals(e.lord(),string(h,"lord"))&&!authority.online(e.lord())&&s.now()-lastSeen(e.lord())>=inactivity){try{authority.validate(e,string(h,"heir"));}catch(IllegalArgumentException invalid){continue;}if(db.one("SELECT id FROM succession_ops WHERE estate=? AND status='PREPARED'",e.id())!=null)continue;String id=prepare(new Actor("система",true),e.id(),true);try{complete(id);}catch(Exception ex){retryAfter.put(id,s.now()+3_600_000L);issues.add(id+": "+ex.getMessage());}}}return issues;
    }
    public List<Map<String,Object>> history(String estate) throws SQLException {return db.query("SELECT * FROM dynasty_history WHERE estate=? ORDER BY seq DESC LIMIT 40",estate);}
}
